const body = $json.body ?? $json;
const request = String(body.request ?? body.prompt ?? '').trim();
if (!request) throw new Error('request is required');
const requestedBranch = String(body.branch ?? 'post-p0/n8n-agent-work');
const forbidden = ['release/q10-q16-closure','main'];
if (forbidden.includes(requestedBranch) || Number(body.pull_request ?? 0) === 14) {
  throw new Error('CK Governor policy deny: protected production subject');
}
if (!/^(post-p0|feat|fix|dev)\//.test(requestedBranch)) {
  throw new Error('CK Governor policy deny: development branch prefix required');
}
return [{json:{request,requested_branch:requestedBranch,mode:'development_only',production_mutation:false,raw_secret_access:false}}];

const req = $json.request;
const roles = [
  ['orchestrator','Decompose goal, enforce policy, consolidate evidence'],
  ['researcher','Find authoritative sources, standards, docs and comparable implementations'],
  ['architect','Design interfaces, invariants, migration and failure boundaries'],
  ['builder','Produce minimal development-only code or patch plan'],
  ['verifier','Define and execute independent tests and evidence checks'],
  ['security_reviewer','Review trust boundaries, secrets, injection, privilege and supply chain risk']
];
return roles.map(([role,mission],i)=>({json:{...$json,role,mission,sequence:i+1,role_prompt:`Goal: ${req}\nRole: ${role}\nMission: ${mission}\nRules: development only; never mutate PR #14/main/release subject; never expose secrets; distinguish proposal/executed/verified.`}}));
